{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Konklusionen 'nej, ikke i sig selv' er korrekt. Svaret påstår dog, at SU-handicaptillæg 'normalt afgøres af SU-myndigheden under Uddannelses- og Forskningsstyrelsen, ikke Udbetaling Danmark'. Det strider mod SU-bekendtgørelsen § 36, stk. 1 og vejledningen, hvor Udbetaling Danmark træffer afgørelsen. Det er en væsentlig juridisk fejl, og svaret besvarer desuden ikke, hvad Udbetaling Danmark vurderer."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret nævner 'hvilke opgaver og timetal ansøgeren kunne klare', men ikke eksplicit, at arbejdets karakter sammenholdes med funktionsnedsættelsen. Det siger ikke, at man vurderer andre typer arbejde ud fra sagens øvrige oplysninger, og skånehensyn nævnes ikke. Timetal svarer kun delvist til 'mindre omfang'. Kritiske elementer mangler derfor."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Første del af spørgsmålet (giver arbejdsophør i sig selv ret?) besvares. Anden del (hvad Udbetaling Danmark vurderer) besvares ikke korrekt, fordi svaret afviser, at Udbetaling Danmark er den relevante myndighed, og ikke beskriver den vurdering, der skal foretages."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovparagraf, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Påstanden om, at SU-myndigheden under Uddannelses- og Forskningsstyrelsen afgør sagerne og ikke Udbetaling Danmark, har ingen støtte i materialet og modsiges af det. Udtrykket 'næsten ikke kan have et erhvervsarbejde' er en omskrivning af 'meget betydelige begrænsninger', som ikke er direkte støttet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer, at arbejdsophør ikke i sig selv giver ret, og at der foretages en konkret vurdering. Det nævner ikke, at arbejde uden fysisk belastning kun er et eksempel, og skånehensyn og andre jobtyper indgår ikke. Det kvalifikationsniveau, som rubrikken kræver, er derfor ikke fuldt bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Det er sammenhængende at konkludere, at arbejdsophør ikke i sig selv er nok, og at en samlet vurdering af varighed og arbejdsevne er afgørende. Fejlen om myndigheden er et selvstændigt udsagn, som ikke gør de øvrige trin indbyrdes modstridende."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret formulerer myndighedsfordelingen som 'normalt ... ikke Udbetaling Danmark'. Det gengiver ikke kilderne, hvor Udbetaling Danmark 'kan' bestemme tildeling. Den øvrige modalitet ('kan være relevant', 'kan indgå') er rimelig, men den centrale fejl vejer tungest."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "partial",
      "reason": "Svaret behandler situationen, hvor arbejde er ophørt pga. funktionsnedsættelsen, og siger, at det ikke i sig selv giver ret. Det nævner ikke, at arbejdets karakter vurderes i forhold til funktionsnedsættelsen, og tilskriver vurderingen en forkert myndighed."
    },
    "A23": {
      "label": "partial",
      "reason": "Svaret berører ansøgerens arbejdsevne, opgaver og timetal, men ikke eksplicit vurderingen af andre typer arbejde eller skånehensyn. Det angiver desuden ikke korrekt, at myndigheden foretager vurderingen."
    }
  },
  "overall_notes": "Svaret har korrekt hovedkonklusion om, at arbejdsophør ikke i sig selv giver ret. Det udelader centrale elementer (arbejdets karakter set i forhold til funktionsnedsættelsen, andre jobtyper, skånehensyn) og fejlagtigt påstår, at SU-myndigheden og ikke Udbetaling Danmark afgør sagerne. Svaret har ingen kildehenvisning."
}

